-- Series to complete: own one copy of every car in a series, claim it once
-- for bonus packs and leaderboard points. Membership is generated by
-- scripts/cars/build-cards.mjs (next migration).

create table public.series (
  id text primary key,
  name text not null,
  kind text not null check (kind in ('brand', 'theme')),
  packs int not null check (packs > 0),
  points int not null check (points > 0)
);

create table public.series_cards (
  series_id text not null references public.series (id) on delete cascade,
  card_slug text not null references public.cards (slug) on delete cascade,
  primary key (series_id, card_slug)
);

create index series_cards_card_idx on public.series_cards (card_slug);

create table public.series_claims (
  user_id uuid not null references auth.users (id) on delete cascade,
  series_id text not null references public.series (id) on delete cascade,
  claimed_at timestamptz not null default now(),
  primary key (user_id, series_id)
);

alter table public.series enable row level security;
alter table public.series_cards enable row level security;
alter table public.series_claims enable row level security;
create policy "Series are public" on public.series for select to anon, authenticated using (true);
create policy "Series cards are public" on public.series_cards for select to anon, authenticated using (true);
create policy "Series claims are public" on public.series_claims for select to anon, authenticated using (true);

/* ---------- Bonus packs: earned, never expire, outside the 10-pack cap ---------- */

alter table public.pack_wallets add column bonus int not null default 0 check (bonus >= 0);

drop function public.my_pack_wallet();

create function public.my_pack_wallet()
returns table (available int, next_at timestamptz, bonus int)
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  w public.pack_wallets;
  gained int;
  avail int;
begin
  if uid is null then
    raise exception 'not authenticated';
  end if;

  insert into public.pack_wallets (user_id) values (uid) on conflict do nothing;
  select * into w from public.pack_wallets where user_id = uid;

  gained := floor(extract(epoch from (now() - w.anchor_at)) / 600)::int;
  avail := least(10, w.stored + gained);

  return query select
    avail,
    case
      when avail >= 10 then null
      else w.anchor_at + make_interval(secs => (gained + 1) * 600)
    end,
    w.bonus;
end;
$$;

create function public.claim_series(p_series text)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  reward int;
begin
  if uid is null then
    raise exception 'not authenticated';
  end if;
  select packs into reward from public.series where id = p_series;
  if not found then
    raise exception 'unknown series';
  end if;
  if exists (select 1 from public.series_claims where user_id = uid and series_id = p_series) then
    raise exception 'already claimed';
  end if;
  if exists (
    select 1 from public.series_cards sc
    where sc.series_id = p_series
      and not exists (select 1 from public.card_copies c where c.card_slug = sc.card_slug and c.owner_id = uid)
  ) then
    raise exception 'series incomplete';
  end if;

  insert into public.series_claims (user_id, series_id) values (uid, p_series);
  insert into public.pack_wallets (user_id) values (uid) on conflict do nothing;
  update public.pack_wallets set bonus = bonus + reward where user_id = uid;
  return reward;
end;
$$;

/* ---------- open_pack: timed packs first, then bonus packs ---------- */

create or replace function public.open_pack(p_pack text)
returns table (copy_id uuid, card_slug text, serial int)
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  uid uuid := (select auth.uid());
  pack_themes text[];
  w public.pack_wallets;
  gained int;
  avail int;
  roll double precision;
  slot_tier text;
  pick text;
  minted_now int;
  new_copy uuid;
  pulled uuid[] := '{}';
  tiers text[] := array['common', 'rare', 'epic', 'legendary'];
begin
  if uid is null then
    raise exception 'not authenticated';
  end if;

  select themes into pack_themes from public.packs where id = p_pack;
  if not found then
    raise exception 'unknown pack';
  end if;

  insert into public.pack_wallets (user_id) values (uid) on conflict do nothing;
  select * into w from public.pack_wallets where user_id = uid for update;

  gained := floor(extract(epoch from (now() - w.anchor_at)) / 600)::int;
  avail := least(10, w.stored + gained);

  if avail >= 1 then
    if w.stored + gained >= 10 then
      update public.pack_wallets set stored = 9, anchor_at = now() where user_id = uid;
    else
      update public.pack_wallets
        set stored = avail - 1,
            anchor_at = w.anchor_at + make_interval(secs => gained * 600)
        where user_id = uid;
    end if;
  elsif w.bonus >= 1 then
    update public.pack_wallets set bonus = bonus - 1 where user_id = uid;
  else
    raise exception 'no packs available' using errcode = 'P0001';
  end if;

  for i in 1..5 loop
    roll := random();
    if i < 5 then
      slot_tier := case
        when roll < 0.60 then 'common'
        when roll < 0.88 then 'rare'
        when roll < 0.97 then 'epic'
        else 'legendary'
      end;
    else
      slot_tier := case
        when roll < 0.75 then 'rare'
        when roll < 0.94 then 'epic'
        else 'legendary'
      end;
    end if;

    pick := null;
    for t in reverse array_position(tiers, slot_tier)..1 loop
      select c.slug into pick
      from public.cards c
      where c.tier = tiers[t] and (c.supply is null or c.minted < c.supply)
      order by -ln(greatest(random(), 1e-12))
               / (case when c.traits && pack_themes then 4 else 1 end)
      limit 1;
      exit when pick is not null;
    end loop;

    if pick is null then
      raise exception 'catalogue sold out';
    end if;

    update public.cards set minted = minted + 1 where slug = pick returning minted into minted_now;
    insert into public.card_copies (card_slug, serial, owner_id, obtained_via)
      values (pick, minted_now, uid, 'pack')
      returning id into new_copy;
    pulled := pulled || new_copy;

    copy_id := new_copy;
    card_slug := pick;
    serial := minted_now;
    return next;
  end loop;

  insert into public.pack_openings (user_id, pack_id, copies) values (uid, p_pack, pulled);
end;
$$;

/* ---------- Leaderboard: claimed series add their points ---------- */

drop function public.leaderboard(int);

create function public.leaderboard(p_limit int default 50)
returns table (
  rank bigint,
  user_id uuid,
  handle text,
  display_name text,
  avatar_url text,
  score bigint,
  distinct_cards bigint,
  copies bigint,
  series bigint
)
language sql
stable
security definer
set search_path = ''
as $$
  with owned as (
    select owner_id, card_slug, count(*) as n
    from public.card_copies
    group by owner_id, card_slug
  ), cards_total as (
    select o.owner_id as uid,
           sum(public.tier_points(c.tier))::bigint as score,
           count(*)::bigint as distinct_cards,
           sum(o.n)::bigint as copies
    from owned o join public.cards c on c.slug = o.card_slug
    group by o.owner_id
  ), series_total as (
    select sc.user_id as uid, sum(s.points)::bigint as score, count(*)::bigint as series
    from public.series_claims sc join public.series s on s.id = sc.series_id
    group by sc.user_id
  ), ranked as (
    select rank() over (
             order by coalesce(c.score, 0) + coalesce(s.score, 0) desc, coalesce(c.distinct_cards, 0) desc
           ) as rank,
           p.id, p.handle, p.display_name, p.avatar_url,
           coalesce(c.score, 0) + coalesce(s.score, 0) as score,
           coalesce(c.distinct_cards, 0) as distinct_cards,
           coalesce(c.copies, 0) as copies,
           coalesce(s.series, 0) as series
    from cards_total c
    full join series_total s on s.uid = c.uid
    join public.profiles p on p.id = coalesce(c.uid, s.uid)
  )
  select * from ranked
  where rank <= p_limit or id = (select auth.uid())
  order by rank, display_name;
$$;

revoke execute on function public.my_pack_wallet() from public, anon;
revoke execute on function public.claim_series(text) from public, anon;
revoke execute on function public.open_pack(text) from public, anon;
grant execute on function public.my_pack_wallet() to authenticated;
grant execute on function public.claim_series(text) to authenticated;
grant execute on function public.open_pack(text) to authenticated;
grant execute on function public.leaderboard(int) to anon, authenticated;
